void SetFileDescriptorAsNonblocking(FileDescriptor fd) {
    assert(IsValidFileDescriptor(fd));
    if (fcntl(fd, F_SETFL, fcntl(fd, F_GETFD) | O_NONBLOCK) < 0) {
        ThrowLastSystemError();
    }
}

